import React, {
  useEffect,
  useRef,
  useState
} from "react";

const ALLOWED_TYPES = new Set([
  "image/jpeg",
  "image/png",
  "image/webp",
  "image/gif",
  "image/heic",
  "image/heif",
  "video/mp4",
  "video/webm",
  "video/quicktime"
]);

const ALLOWED_EXTENSIONS =
  /\.(jpg|jpeg|png|webp|gif|heic|heif|mp4|webm|mov)$/i;

const MAX_FILE_SIZE = 50 * 1024 * 1024;

export default function UploadArea({
  category,
  notify
}) {
  const [files, setFiles] = useState([]);
  const [dragging, setDragging] = useState(false);
  const [loading, setLoading] = useState(false);

  const inputRef = useRef(null);
  const filesRef = useRef([]);

  useEffect(() => {
    filesRef.current = files;
  }, [files]);

  useEffect(() => {
    return () => {
      filesRef.current.forEach((item) => {
        URL.revokeObjectURL(item.preview);
      });
    };
  }, []);

  function validateFile(file) {
    const validType = ALLOWED_TYPES.has(file.type);

    const validExtension =
      ALLOWED_EXTENSIONS.test(file.name);

    if (!validType || !validExtension) {
      return "Unsupported file format";
    }

    if (file.size === 0) {
      return "Empty files are not allowed";
    }

    if (file.size > MAX_FILE_SIZE) {
      return "File exceeds 50 MB";
    }

    return null;
  }

  function handleFiles(fileList) {
    const accepted = [];
    const rejected = [];

    Array.from(fileList).forEach((file) => {
      const error = validateFile(file);

      if (error) {
        rejected.push(`${file.name}: ${error}`);
        return;
      }

      accepted.push({
        id: crypto.randomUUID(),
        file,
        preview: URL.createObjectURL(file)
      });
    });

    if (accepted.length > 0) {
      setFiles((previous) => [
        ...previous,
        ...accepted
      ]);
    }

    if (rejected.length > 0) {
      notify(
        `${rejected.length} file(s) rejected. ${rejected[0]}`,
        "error"
      );
    } else if (accepted.length > 0) {
      notify(
        `${accepted.length} valid file(s) added.`
      );
    }
  }

  function handleDrop(event) {
    event.preventDefault();
    setDragging(false);

    handleFiles(event.dataTransfer.files);
  }

  function handleDragOver(event) {
    event.preventDefault();
    setDragging(true);
  }

  function handleDragLeave(event) {
    event.preventDefault();

    if (!event.currentTarget.contains(event.relatedTarget)) {
      setDragging(false);
    }
  }

  function removeFile(id) {
    setFiles((previous) => {
      const selected = previous.find(
        (item) => item.id === id
      );

      if (selected) {
        URL.revokeObjectURL(selected.preview);
      }

      return previous.filter(
        (item) => item.id !== id
      );
    });
  }

  function handleUpload() {
    if (files.length === 0) {
      notify("Please select files first.", "error");
      return;
    }

    setLoading(true);

    setTimeout(() => {
      setLoading(false);

      notify(
        `${files.length} file(s) validated for ${category}. Demo only — files were not sent to a server.`
      );
    }, 1000);
  }

  function formatSize(bytes) {
    return (bytes / (1024 * 1024)).toFixed(2);
  }

  return (
    <div className="upload-panel">
      <div className="upload-panel-header">
        <div>
          <h3>Add to {category}</h3>
          <p>
            Choose your favorite shots and footage.
          </p>
        </div>

        <span className="file-count">
          {files.length} selected
        </span>
      </div>

      <div
        className={`drop-zone ${
          dragging ? "dragging" : ""
        }`}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
      >
        <div className="upload-icon">⇧</div>

        <h3>Drag photos & videos here</h3>

        <p>
          Or browse files from your device
        </p>

        <button
          type="button"
          className="browse-button"
          onClick={() => inputRef.current.click()}
        >
          Browse files
        </button>

        <input
          ref={inputRef}
          type="file"
          multiple
          hidden
          accept="image/jpeg,image/png,image/webp,image/gif,image/heic,image/heif,video/mp4,video/webm,video/quicktime,.jpg,.jpeg,.png,.webp,.gif,.heic,.heif,.mp4,.webm,.mov"
          onChange={(event) => {
            handleFiles(event.target.files);
            event.target.value = "";
          }}
        />

        <small>
          JPG, PNG, WEBP, GIF, HEIC, HEIF,
          MP4, WEBM, MOV · Maximum 50 MB per file
        </small>
      </div>

      {files.length > 0 && (
        <div className="selected-files-section">
          <div className="selected-files-heading">
            <h3>Selected files</h3>
            <span>{files.length} ready</span>
          </div>

          <div className="file-preview-grid">
            {files.map((item) => (
              <div
                className="file-preview-card"
                key={item.id}
              >
                {item.file.type.startsWith("image/") ? (
                  <img
                    src={item.preview}
                    alt={item.file.name}
                  />
                ) : (
                  <div className="video-placeholder">
                    <span>▶</span>
                    <small>VIDEO</small>
                  </div>
                )}

                <button
                  type="button"
                  className="remove-file"
                  aria-label={`Remove ${item.file.name}`}
                  onClick={() => removeFile(item.id)}
                >
                  ×
                </button>

                <div className="file-info">
                  <strong title={item.file.name}>
                    {item.file.name}
                  </strong>

                  <small>
                    {formatSize(item.file.size)} MB
                  </small>
                </div>
              </div>
            ))}
          </div>

          <button
            className="primary-button confirm-button"
            onClick={handleUpload}
            disabled={loading}
          >
            {loading ? (
              <>
                <span className="spinner" />
                Validating files...
              </>
            ) : (
              <>
                ✓ Confirm selection
              </>
            )}
          </button>
        </div>
      )}
    </div>
  );
}
